entries[113858] = { ["name"] = "Finstere Seele: Instabilität", ["text"] = "5% von Grundmana\nSofort 2 min Abklingzeit\nErfüllt Eure Seele mit einer instabilen Macht, die Eure kritische Trefferchance 20 Sek. lang um 30% erhöht. [ Glyphe 'Finstere Seele' : Passiv:\nErhöht Eure kritische Trefferchance um 3%. Während der Zauber von Abklingzeit betroffen ist, ist dieser Effekt inaktiv ]" }
