entries[113860] = { ["name"] = "Finstere Seele: Elend", ["text"] = "5% von Grundmana\nSofort 2 min Abklingzeit\nErfüllt Eure Seele mit dem Klagen gefallener Helden, wodurch Euer Zaubertempo 20 Sek. lang um 30% erhöht wird. [ Glyphe 'Finstere Seele' : Passiv:\nErhöht Euer Zaubertempo um 3%. Während der Zauber von Abklingzeit betroffen ist, ist dieser Effekt inaktiv ]" }
entries[113861] = { ["name"] = "Finstere Seele: Wissen", ["text"] = "5% von Grundmana\nSofort 2 min Abklingzeit\nEure Seele wird von dämonischem Wissen erfüllt, das Eure Meisterschaft 'Meister der Dämonologie' 20 Sek. lang um zusätzliche 30% erhöht. [ Glyphe 'Finstere Seele' : Passiv:\nErhöht Eure Meisterschaft 'Meister der Dämonologie' um zusätzliche 3%. Während der Zauber von Abklingzeit betroffen ist, ist dieser Effekt inaktiv ]" }
entries[113862] = { ["name"] = "Große Unsichtbarkeit", ["text"] = "Sofort\nMacht den Zaubernden sofort unsichtbar, verringert jegliche Bedrohung und entfernt zwei Effekte, die regelmäßigen Schaden verursachen. Während Ihr unsichtbar seid, können Feinde Euch nicht anvisieren. Hält 20 Sek. lang an. [ Glyphe 'Unsichtbarkeit' : Während Ihr unsichtbar seid, wird Euer Bewegungstempo um 40% erhöht ] Der Effekt wird abgebrochen, wenn Ihr Aktionen ausführt.\n\nWährend Ihr unsichtbar seid und 3 Sek. lang nach Ende dieses Effekts ist der von Euch erlittene Schaden um 90% verringert.\n\nErsetzt 'Unsichtbarkeit'." }
