entries[113952] = { ["name"] = "Betäubendes Gift", ["text"] = "Unbegrenzte Reichweite\nSofort\nÜberzieht Eure Waffen mit einem nicht-tödlichen Gift, das 1 Stunde lang an ihnen haften bleibt. Bei jedem Schlag besteht eine Chance von 20%, den Gegner zu vergiften. Das Gift ist bis zu 4-mal auf einem einzelnen Ziel stapelbar. Beim Erreichen des vierten Stapels wird der Betroffene 4 Sek. lang betäubt." }
entries[113953] = { ["name"] = "Paralyse", ["text"] = "Unbegrenzte Reichweite\nSofort\nÜberzieht Eure Waffen mit einem nicht-tödlichen Gift, das 1 Stunde lang an ihnen haften bleibt. Bei jedem Schlag besteht eine Chance von 20%, den Gegner zu vergiften. Das Gift wirkt 15 Sek. lang und ist bis zu 4-mal auf einem einzelnen Ziel stapelbar. Beim Erreichen des vierten Stapels wird der Betroffene 4 Sek. lang betäubt. [ Tückische Klinge : Effekt von 'Tückische Klinge':\nRuft eine sofortige Lähmung des Unterkörpers des Ziels hervor, wodurch es 4 Sek. lang bewegungsunfähig wird ]" }
