entries[114029] = { ["name"] = "Sicherung", ["text"] = "Ersetzt Einschreiten\n25 Meter Reichweite\nSofort 30 sek. Abklingzeit\nLauft mit hoher Geschwindigkeit auf ein Gruppen- oder Schlachtzugsmitglied zu, entfernt sämtliche bewegungseinschränkenden Effekte von Euch, fängt den nächsten Nahkampf- oder Distanzangriff gegen dieses Ziel ab und verringert den von ihm erlittenen Schaden 6 Sek. lang um 20%.\n\nErsetzt 'Einschreiten'." }
