entries[114112] = { ["name"] = "Handschuhsockel", ["text"] = "Wirken in 1.5 sek.\nBenötigt Handschuhe\nTools: Schmiedehammer\nReagenzien:\nStarker Fluxus (4)\nBringt an Euren Handschuhen dauerhaft einen Sockel an.\n\nEinem Gegenstand kann nicht mehr als ein zusätzlicher Sockel hinzugefügt werden. Der Träger benötigt die Fertigkeit der Schmiedekunst, sonst wird der Sockel inaktiv." }
