entries[114157] = { ["name"] = "Richtspruch", ["text"] = "40 Meter Reichweite\nSofort 1 min Abklingzeit\nEin Hammer fällt langsam vom Himmel und verursacht im Verlauf von 10 Sek. (Zaubermacht * 5936 / 1000 + 26.72716306 * 486 ) Heiligschaden. Der Schaden erfolgt anfangs nur langsam, nimmt dann zu und endet mit einem finalen Schadensschub. Beim Bannen des Effekts wird der finale Schadensschub ausgelöst.\n\nHinrichtungsaufschub\nWenn der Zauber auf befreundete Ziele angewandt wird, heilt der fallende Hammer das Ziel im Verlauf von 10 Sek. um (Zaubermacht * 5936 / 1000 + 26.72716306 * 486 ). Die Heilung erfolgt anfangs nur langsam, nimmt dann zu und endet mit einem finalen Heilungsschub. Beim Bannen des Effekts wird der finale Heilungsschub ausgelöst." }
entries[114158] = { ["name"] = "Hammer des Lichts", ["text"] = "30 Meter Reichweite\nSofort 1 min Abklingzeit\nSchleudert einen lichtgetränkten Hammer in den Boden, wo er einen Bereich von 10 Metern 14 Sek. lang mit überspringendem Licht überzieht.\n\nÜberspringendes Licht\nFügt Gegnern innerhalb des Effektbereichs 3631 Heiligschaden zu und verringert ihr Bewegungstempo 2 Sek. lang um 50%. Heilt Verbündete alle 2 Sek. um 3631 ." }
